(() => {
'use strict';
const KEY='learning-studio:v1';
const leafTopics=()=>tracks.flatMap(t=>t.modules.flatMap(m=>m.children.map(x=>({...x,trackId:t.id,trackTitle:t.title,moduleId:m.id,moduleTitle:m.title}))));
let topics=leafTopics(), topicById=Object.fromEntries(topics.map(t=>[t.id,t]));const resourceById=Object.fromEntries(resources.map(r=>[r.id,r]));
const icon={dashboard:'◫',roadmap:'⌘',analytics:'◷',resources:'↗',notes:'▤',planner:'▦',projects:'◈',bookmarks:'☆',settings:'⚙'};
const nav=[['dashboard','Overview'],['roadmap','Learning roadmap'],['analytics','Progress analytics'],['resources','Resource library'],['notes','Notes & knowledge'],['planner','Study planner'],['projects','Projects & labs'],['bookmarks','Bookmarks'],['settings','Settings']];
let saved=true, state=loadState(), view='dashboard', modal=null, filters={query:'',track:'all',status:'all',difficulty:'all',priority:'all',sort:'order'}, expanded=new Set(['foundations','cybersecurity','ai','aisec','projects']), mobileMenu=false, toastTimer;
hydrateCustomTopics();
function hydrateCustomTopics(){for(const x of state.customTopics||[]){const track=tracks.find(t=>t.id===(x.trackId||'foundations'));if(!track)continue;let mod=track.modules.find(m=>m.id===x.moduleId||m.title===(x.moduleTitle||'My topics'));if(!mod){mod={id:x.moduleId||`custom-module-${x.id}`,title:x.moduleTitle||'My topics',level:x.level||'Beginner',desc:x.isProject?'Custom project':'Custom module',dependencies:[],children:[]};track.modules.push(mod)}if(x.isProject){for(const [i,milestone] of (x.milestones||[]).entries())if(!mod.children.some(c=>c.id===milestone.id))mod.children.push({...milestone,type:'topic',dependencies:[]})}else if(!mod.children.some(c=>c.id===x.id))mod.children.push({...x,type:'topic',dependencies:[]})}topics=leafTopics();topicById=Object.fromEntries(topics.map(t=>[t.id,t]))}
function baseState(){return {schemaVersion:1,progress:{},notes:[],sessions:[],bookmarkedTopics:[],bookmarkedResources:[],hiddenContinue:[],settings:{theme:'system',weeklyGoal:6,preferredTracks:[],defaultDifficulty:'all',customTags:[],categories:[]},customTopics:[],customResources:[],projectDetails:{}}}
function loadState(){try{const raw=localStorage.getItem(KEY);if(!raw)return baseState();const parsed=JSON.parse(raw);if(!parsed||typeof parsed!=='object'||parsed.schemaVersion!==1)throw Error('Unsupported backup format');return {...baseState(),...parsed,progress:parsed.progress||{},settings:{...baseState().settings,...parsed.settings}}}catch(e){console.warn('Saved data could not be read. A fresh workspace is available.',e);return baseState()}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saved=true;updateSaveBadge()}catch(e){saved=false;updateSaveBadge();toast('Could not save to browser storage. Export a backup before leaving.','error')}}
function markDirty(){saved=false;updateSaveBadge();save()}
function updateSaveBadge(){const b=document.querySelector('#save-state');if(b){b.textContent=saved?'Saved locally':'Saving…';b.classList.toggle('unsaved',!saved)}}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pct(n,d){return d?Math.round(n/d*100):0}
function statusOf(id){return state.progress[id]?.status||'Not Started'}
function allLeafIn(nodes){return nodes.flatMap(m=>m.children)}
function calc(nodes){const leaves=nodes.flatMap(n=>n.children||n.modules?.flatMap(m=>m.children)||[]).filter(Boolean),done=leaves.filter(t=>statusOf(t.id)==='Completed').length,doing=leaves.filter(t=>statusOf(t.id)==='In Progress').length,estimated=leaves.reduce((s,t)=>s+(t.hours||1),0),actual=leaves.reduce((s,t)=>s+(Number(state.progress[t.id]?.actualHours)||0),0);return {total:leaves.length,done,doing,remaining:leaves.length-done,estimated,actual,percent:pct(done,leaves.length)}}
function trackById(id){return tracks.find(t=>t.id===id)}
function getLeaves(trackId='all'){return topics.filter(t=>trackId==='all'||t.trackId===trackId)}
function textSearch(item){return [item.title,item.desc,item.trackTitle,item.moduleTitle,(item.tags||[]).join(' ')].join(' ').toLowerCase()}
function trackStats(t){return calc(t.modules)}
function formatHours(n){return Number(n.toFixed(1))}
function dateLabel(value,opts={month:'short',day:'numeric'}){if(!value)return 'No date';let d=new Date(`${value}T12:00:00`);return Number.isNaN(+d)?'No date':new Intl.DateTimeFormat('en-US',opts).format(d)}
function isCompletedRecently(){return topics.filter(t=>state.progress[t.id]?.status==='Completed').sort((a,b)=>(state.progress[b.id]?.completedAt||'').localeCompare(state.progress[a.id]?.completedAt||'')).slice(0,4)}
function currentFocus(){const hidden=new Set(state.hiddenContinue||[]);return topics.find(t=>statusOf(t.id)==='In Progress'&&!hidden.has(t.id))||topics.find(t=>statusOf(t.id)==='Not Started'&&!hidden.has(t.id))}
function resourcesFor(ids=[]){return ids.map(id=>resourceById[id]||state.customResources.find(r=>r.id===id)).filter(Boolean)}
function badgeStatus(status){const cls=status==='Completed'?'complete':status==='In Progress'?'active':'pending';return `<span class="status ${cls}">${esc(status)}</span>`}
function progressBar(value,color='blue'){return `<div class="progress-track"><span class="progress-fill ${color}" style="width:${value}%"></span></div>`}
function trackProgressCard(t){const s=trackStats(t);return `<button class="track-card ${t.color}" data-action="open-track" data-track="${t.id}"><span class="track-icon">${t.icon}</span><span class="track-copy"><b>${esc(t.title)}</b><small>${s.done} of ${s.total} topics · ${s.estimated}h planned</small>${progressBar(s.percent,t.color)}</span><strong>${s.percent}%</strong></button>`}
function render(){document.documentElement.dataset.theme=getTheme();document.getElementById('app').innerHTML=`<div class="shell ${mobileMenu?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#dashboard" data-view="dashboard"><span class="brand-mark">L</span><span>Learning<span class="brand-light">Studio</span><small>CYBERSECURITY × AI</small></span></a><div class="side-label">WORKSPACE</div><nav>${nav.map(([id,label])=>`<button class="nav-link ${view===id?'selected':''}" data-view="${id}"><span>${icon[id]}</span>${label}${id==='notes'&&state.notes.length?`<em>${state.notes.length}</em>`:''}</button>`).join('')}</nav><div class="side-spacer"></div><div class="sidebar-progress"><div class="mini-top"><span>Overall progress</span><b>${calc(tracks).percent}%</b></div>${progressBar(calc(tracks).percent,'blue')}<small>${calc(tracks).done} of ${calc(tracks).total} topics completed</small></div><div class="profile"><div class="avatar">LS</div><div><b>My learning space</b><small>Private · saved on this device</small></div><button aria-label="Open settings" data-view="settings">•••</button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="breadcrumbs">Learning space <span>/</span> <b>${nav.find(n=>n[0]===view)?.[1]||'Overview'}</b></div><div class="top-actions"><label class="global-search"><span>⌕</span><input id="global-search" placeholder="Search topics, notes, resources…" value="${esc(window.globalQuery||'')}" aria-label="Search everything"><kbd>⌘ K</kbd></label><div class="search-results" id="search-results"></div><span id="save-state" class="save-state">${saved?'Saved locally':'Saving…'}</span><button class="icon-button theme-button" data-action="theme" aria-label="Toggle color theme" title="Toggle theme">${getTheme()==='dark'?'☼':'◐'}</button></div></header><div class="content">${renderView()}</div></main></div>${modal?renderModal():''}<div class="toast" id="toast" role="status"></div>`;bind();updateSaveBadge()}
function getTheme(){const t=state.settings.theme;if(t==='dark'||t==='light')return t;return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}
function renderView(){switch(view){case'roadmap':return renderRoadmap();case'analytics':return renderAnalytics();case'resources':return renderResources();case'notes':return renderNotes();case'planner':return renderPlanner();case'projects':return renderProjects();case'bookmarks':return renderBookmarks();case'settings':return renderSettings();default:return renderDashboard()}}
function headerKicker(title,sub,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${sub}</span><h1>${title}</h1></div><div class="heading-actions">${actions}</div></div>`}
function renderDashboard(){const s=calc(tracks),focus=currentFocus(),weekly=weeklyHours(),upcoming=state.sessions.filter(x=>x.status!=='Done'&&x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3),recent=isCompletedRecently(),notes=[...state.notes].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3),bookmarked=state.bookmarkedResources.map(id=>resourceById[id]).filter(Boolean).slice(0,3);return `${headerKicker('Your learning, at a glance','PERSONAL LEARNING SPACE',`<button class="button ghost" data-action="export">↧ <span>Back up data</span></button><button class="button primary" data-view="roadmap">Continue learning <span>→</span></button>`)}<section class="hero-card"><div class="hero-copy"><div class="hero-kicker"><span class="live-dot"></span> YOUR JOURNEY STARTS HERE</div><h2>Build skills that<br>work <i>in the real world.</i></h2><p>A structured path from technical foundations to secure AI systems, shaped around your pace.</p><div class="hero-actions"><button class="button light" data-action="continue">${focus?'Pick up where you left off':'Explore the roadmap'} <span>→</span></button><button class="text-button" data-view="planner">Plan a study session <span>↗</span></button></div></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit-center">${s.percent}<small>%</small><span>COMPLETE</span></div><span class="orbit-node n1">⌘</span><span class="orbit-node n2">✳</span><span class="orbit-node n3">⛨</span><span class="orbit-node n4">◈</span></div><div class="hero-foot"><span>↗ <b>${s.done}</b> topics completed</span><span>◷ <b>${formatHours(s.actual)}h</b> time invested</span><span>⌖ <b>${state.sessions.length}</b> planned sessions</span></div></section><div class="stats-row"><article class="stat-card"><div class="stat-icon lavender">✓</div><div><span>Completed</span><b>${s.done}<small> topics</small></b></div><span class="stat-foot">${s.total?`${pct(s.done,s.total)}% of your path`:''}</span></article><article class="stat-card"><div class="stat-icon peach">◷</div><div><span>In progress</span><b>${s.doing}<small> topics</small></b></div><span class="stat-foot">Keep your momentum</span></article><article class="stat-card"><div class="stat-icon mint">⌑</div><div><span>Study time</span><b>${formatHours(s.actual)}<small> / ${s.estimated}h</small></b></div><span class="stat-foot">${formatHours(s.estimated-s.actual)}h estimated remaining</span></article><article class="stat-card"><div class="stat-icon sky">▦</div><div><span>This week</span><b>${formatHours(weekly.actual)}<small> / ${state.settings.weeklyGoal}h</small></b></div><span class="stat-foot">${Math.max(0,formatHours(state.settings.weeklyGoal-weekly.actual))}h to weekly goal</span></article></div><div class="section-row"><div><span class="eyebrow">THE BIG PICTURE</span><h2>Your learning tracks</h2></div><button class="subtle-link" data-view="analytics">View analytics →</button></div><section class="track-grid">${tracks.map(trackProgressCard).join('')}</section><div class="dashboard-columns"><section class="panel continue-panel"><div class="panel-heading"><div><span class="eyebrow">KEEP THE MOMENTUM</span><h2>Continue learning</h2></div><div class="heading-actions">${(state.hiddenContinue||[]).length?`<button class="subtle-link" data-action="restore-continue">Restore skipped (${state.hiddenContinue.length})</button>`:''}<button class="subtle-link" data-view="roadmap">View roadmap →</button></div></div>${focus?topicRow(focus,true):empty('⌘','Your next step is waiting',(state.hiddenContinue||[]).length?'You removed every suggested topic from this list. Restore them or choose a topic in the roadmap.':'Choose a topic in the roadmap to get started.')}</section><section class="panel focus-panel"><div class="panel-heading"><div><span class="eyebrow">RECOMMENDED NEXT</span><h2>Your current focus</h2></div><span class="focus-mark">✦</span></div>${focus?`<div class="focus-track">${trackById(focus.trackId)?.title} <span>·</span> ${focus.moduleTitle}</div><h3>${esc(focus.title)}</h3><p>${esc(focus.desc||'Build a strong foundation with a short focused study session.')}</p><div class="focus-meta"><span>◷ ${focus.hours}h estimated</span><span>${focus.level}</span></div><button class="button primary full" data-topic="${focus.id}">Open learning detail →</button>`:empty('✓','Great work','You completed every topic.')}</section></div><div class="dashboard-columns lower-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">YOUR CALENDAR</span><h2>Upcoming sessions</h2></div><button class="small-add" data-action="new-session">＋</button></div>${upcoming.length?upcoming.map(sessionRow).join(''):empty('▦','Nothing scheduled yet','Add a session to make room for learning.')}</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">KNOWLEDGE BASE</span><h2>Recently edited notes</h2></div><button class="subtle-link" data-view="notes">All notes →</button></div>${notes.length?notes.map(noteRow).join(''):empty('▤','Keep what you learn','Create a note for a concept, command or question.')}</section></div><section class="panel recent-panel"><div class="panel-heading"><div><span class="eyebrow">SMALL WINS ADD UP</span><h2>Recently completed</h2></div></div>${recent.length?`<div class="recent-list">${recent.map(t=>`<button class="recent-topic" data-topic="${t.id}"><span class="checkmark">✓</span><span><b>${esc(t.title)}</b><small>${t.trackTitle} · ${dateLabel(state.progress[t.id]?.completedAt)}</small></span><span>→</span></button>`).join('')}</div>`:empty('✧','Your wins will show up here','Complete a topic and it will appear in your activity.')}</section><footer class="data-note">Your learning data is stored privately in this browser. <button data-action="export">Download a backup</button></footer>`}
function empty(mark,title,desc){return `<div class="empty-state"><span>${mark}</span><b>${title}</b><p>${desc}</p></div>`}
function weeklyHours(){const since=new Date();since.setDate(since.getDate()-6);const actual=state.sessions.filter(s=>s.status==='Done'&&new Date(`${s.date}T23:59:00`)>=since).reduce((n,s)=>n+(Number(s.actualHours)||Number(s.hours)||0),0);return {actual}}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function topicRow(t,full=false){const st=statusOf(t.id);return `<div class="topic-row"><button class="topic-title" data-topic="${t.id}"><span class="topic-marker ${st==='Completed'?'marked':''}">${st==='Completed'?'✓':st==='In Progress'?'◒':'○'}</span><span><b>${esc(t.title)}</b><small>${t.moduleTitle}${full?` · ${t.trackTitle}`:''}</small></span></button><span class="topic-time">◷ ${t.hours}h</span>${badgeStatus(st)}${full?`<button class="row-remove" data-action="remove-continue" data-id="${t.id}" aria-label="Remove ${esc(t.title)} from Continue Learning" title="Remove from Continue Learning">×</button>`:''}<button class="row-arrow" data-topic="${t.id}" aria-label="Open ${esc(t.title)}">→</button></div>`}
function renderRoadmap(){
 const q=filters.query.toLowerCase();
 const shownTrack=filters.track==='all'?tracks:tracks.filter(t=>t.id===filters.track);
 const nodes=shownTrack.map(t=>{
  const modules=t.modules.map(m=>{
   const children=m.children.filter(x=>{
    const st=statusOf(x.id);
    return (!q||textSearch({...x,trackTitle:t.title,moduleTitle:m.title}).includes(q))
     &&(filters.status==='all'||st===filters.status)
     &&(filters.difficulty==='all'||x.level===filters.difficulty)
     &&(filters.priority==='all'||(state.progress[x.id]?.priority||'Medium')===filters.priority);
   });
   return {...m,children};
  }).filter(m=>m.children.length);
  return {...t,modules};
 }).filter(t=>t.modules.length);
 const visible=nodes.reduce((n,t)=>n+t.modules.reduce((m,x)=>m+x.children.length,0),0);
 return `${headerKicker('Learning roadmap','THE CURRICULUM',`<button class="button ghost" data-action="add-topic">＋ Add a topic</button><button class="button primary" data-action="expand-all">Expand all</button>`)}<section class="roadmap-intro"><div><h2>Learn it in the right order.</h2><p>From core computing skills to securing AI agents. Each step builds on the ones before it.</p><div class="roadmap-chips"><span>⌑ 5 tracks</span><span>⌘ ${topics.length} learning topics</span><span>◷ ${calc(tracks).estimated} estimated hours</span></div></div><div class="intro-progress"><strong>${calc(tracks).percent}%</strong><small>OVERALL</small>${progressBar(calc(tracks).percent,'blue')}</div></section><div class="filter-bar"><label class="filter-search">⌕ <input id="roadmap-search" placeholder="Search the curriculum…" value="${esc(filters.query)}"></label><select id="filter-track" aria-label="Filter by track"><option value="all">All tracks</option>${tracks.map(t=>`<option value="${t.id}" ${filters.track===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select><select id="filter-status" aria-label="Filter by status"><option value="all">All statuses</option>${['Not Started','In Progress','Completed'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="filter-difficulty" aria-label="Filter by difficulty"><option value="all">All levels</option>${['Beginner','Intermediate','Advanced'].map(x=>`<option ${filters.difficulty===x?'selected':''}>${x}</option>`).join('')}</select><select id="filter-priority" aria-label="Filter by priority"><option value="all">All priorities</option>${['High','Medium','Low'].map(x=>`<option ${filters.priority===x?'selected':''}>${x}</option>`).join('')}</select><select id="filter-sort" aria-label="Sort topics"><option value="order">Suggested order</option><option value="name">Name A–Z</option><option value="priority">Priority</option><option value="hours">Study time</option><option value="status">Status</option><option value="date">Target date</option></select></div><div class="roadmap-filter-summary"><span>${visible} topics shown</span><button class="text-button" data-action="reset-filters">Reset filters</button></div><div class="roadmap-list">${nodes.length?nodes.map(t=>trackSection(t)).join(''):empty('⌕','No matching topics','Try changing your search or filters.')}</div><div class="curriculum-method"><span>ⓘ</span><p><b>How progress works</b> Topics are the counted learning units. Module and track progress is calculated from their child topics; finishing a parent never checks off children automatically.</p></div>`
}
function trackSection(t){const s=trackStats(t);return `<section class="roadmap-track ${t.color}"><button class="track-section-head" data-action="toggle-track" data-track="${t.id}" aria-expanded="${expanded.has(t.id)}"><span class="track-icon">${t.icon}</span><span class="track-section-title"><b>${esc(t.title)}</b><small>${esc(t.description)}</small></span><span class="track-section-count">${s.done}/${s.total}</span><span class="track-section-percent">${s.percent}%</span><span class="chevron">${expanded.has(t.id)?'⌄':'›'}</span></button>${progressBar(s.percent,t.color)}${expanded.has(t.id)?`<div class="module-list">${t.modules.map(m=>moduleSection(t,m)).join('')}</div>`:''}</section>`}
function moduleSection(t,m){const ids=m.children,done=ids.filter(x=>statusOf(x.id)==='Completed').length,per=pct(done,ids.length);return `<section class="module"><button class="module-head" data-action="toggle-module" data-module="${m.id}" aria-expanded="${expanded.has(m.id)}"><span class="module-caret">${expanded.has(m.id)?'⌄':'›'}</span><span class="module-name"><b>${esc(m.title)}</b><small>${esc(m.desc)}</small></span><span class="module-meta">${done}/${ids.length} · ${per}%</span></button>${expanded.has(m.id)?`<div class="module-topics">${sortItems(ids).map(tpc=>roadmapTopic(t,tpc)).join('')}</div>`:''}</section>`}
function sortItems(arr){let a=[...arr];switch(filters.sort){case'name':return a.sort((x,y)=>x.title.localeCompare(y.title));case'hours':return a.sort((x,y)=>x.hours-y.hours);case'priority':return a.sort((x,y)=>({'High':0,'Medium':1,'Low':2}[state.progress[x.id]?.priority||'Medium']-({'High':0,'Medium':1,'Low':2}[state.progress[y.id]?.priority||'Medium'])));case'status':return a.sort((x,y)=>statusOf(x.id).localeCompare(statusOf(y.id)));case'date':return a.sort((x,y)=>(state.progress[x.id]?.targetDate||'9999').localeCompare(state.progress[y.id]?.targetDate||'9999'));default:return a}}
function roadmapTopic(t,x){const st=statusOf(x.id),b=state.bookmarkedTopics.includes(x.id);return `<article class="roadmap-topic ${st==='Completed'?'is-complete':''}"><label class="topic-check"><input type="checkbox" data-topic-check="${x.id}" ${st==='Completed'?'checked':''} aria-label="Mark ${esc(x.title)} complete"><span class="custom-check">✓</span></label><button class="roadmap-topic-main" data-topic="${x.id}"><b>${esc(x.title)}</b><small>${esc(x.desc||'Open the topic to see learning notes and related resources.')}</small><span class="topic-tags"><i>${x.level}</i><i>◷ ${x.hours}h</i>${x.dependencies?.length?`<i>Prerequisite</i>`:''}</span></button><select data-topic-status="${x.id}" class="status-select ${st==='Completed'?'is-done':st==='In Progress'?'is-active':''}" aria-label="Status for ${esc(x.title)}">${['Not Started','In Progress','Completed'].map(v=>`<option ${st===v?'selected':''}>${v}</option>`).join('')}</select><button class="bookmark-control ${b?'bookmarked':''}" data-bookmark-topic="${x.id}" aria-label="${b?'Remove bookmark':'Bookmark'} ${esc(x.title)}">${b?'★':'☆'}</button><button class="row-arrow" data-topic="${x.id}" aria-label="Details">→</button></article>`}
function renderAnalytics(){const s=calc(tracks),trend=completionTrend(),detailed=state.settings.detailedAnalytics!==false;return `${headerKicker('Progress analytics','YOUR MOMENTUM',`<button class="button ghost" data-action="toggle-detail">${detailed?'Simplified view':'Detailed view'}</button>`)}<section class="analytics-hero"><div><span class="eyebrow">CURRICULUM COMPLETION</span><div class="big-percent">${s.percent}<span>%</span></div><p>${s.done} completed · ${s.doing} in progress · ${s.remaining} not started</p></div><div class="ring" style="--progress:${s.percent}%"><div><b>${s.percent}%</b><small>COMPLETE</small></div></div><div class="analytics-hours"><div><small>ESTIMATED LEARNING</small><b>${s.estimated}<span>h</span></b></div><div><small>TIME LOGGED</small><b>${formatHours(s.actual)}<span>h</span></b></div></div></section><div class="analytics-grid"><section class="panel chart-panel"><div class="panel-heading"><div><span class="eyebrow">COMPLETION HISTORY</span><h2>Steady progress over time</h2></div><span class="muted-caption">Based on saved completion dates</span></div>${trend.length?`<div class="chart-area"><div class="chart-y"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="chart-bars">${trend.map(x=>`<div class="chart-column"><div class="chart-track"><span style="height:${x.value}%"></span></div><small>${esc(x.label)}</small><b>${x.value}%</b></div>`).join('')}</div></div>`:empty('◷','Your progress timeline starts with a completed topic','Completion history appears here as you work through the curriculum.')}</section><section class="panel status-panel"><div class="panel-heading"><div><span class="eyebrow">AT A GLANCE</span><h2>Topic status</h2></div></div><div class="status-breakdown">${[['Completed',s.done,'complete'],['In progress',s.doing,'active'],['Not started',s.remaining,'pending']].map(a=>`<div><span class="legend-dot ${a[2]}"></span><span>${a[0]}</span><b>${a[1]}</b><small>${pct(a[1],s.total)}%</small></div>`).join('')}</div>${progressBar(s.percent,'blue')}<p class="muted-caption">Each learning topic is counted once. Project milestones count as project topics.</p></section></div><section class="panel track-analytics"><div class="panel-heading"><div><span class="eyebrow">TRACK BREAKDOWN</span><h2>Progress by learning track</h2></div></div>${tracks.map(t=>{let x=trackStats(t);return `<button class="analytics-track ${t.color}" data-action="open-track" data-track="${t.id}"><span class="track-icon">${t.icon}</span><span class="track-analytics-main"><b>${esc(t.title)}</b>${progressBar(x.percent,t.color)}<small>${x.done} complete · ${x.remaining} remaining · ${x.estimated}h planned · ${formatHours(x.actual)}h logged</small></span><strong>${x.percent}%</strong><span>→</span></button>`}).join('')}</section>${detailed?`<div class="section-row"><div><span class="eyebrow">MODULE DETAIL</span><h2>Where you are in each track</h2></div></div><div class="module-analytics">${tracks.map(t=>`<section class="panel module-analytics-card"><h3>${t.icon} ${esc(t.title)}</h3>${t.modules.map(m=>{let done=m.children.filter(x=>statusOf(x.id)==='Completed').length;return `<div class="module-progress-line"><span>${esc(m.title)}</span><b>${pct(done,m.children.length)}%</b>${progressBar(pct(done,m.children.length),t.color)}<small>${done}/${m.children.length}</small></div>`}).join('')}</section>`).join('')}</div>`:''}`}
function completionTrend(){const dated=topics.map(t=>state.progress[t.id]?.completedAt).filter(Boolean).map(x=>new Date(x));if(!dated.length)return [];const now=new Date(),vals=[];for(let w=5;w>=0;w--){const end=new Date(now);end.setDate(end.getDate()-w*7);const count=dated.filter(d=>d<=end).length;vals.push({label:w===0?'This wk':`${w} wk${w>1?'s':''}`,value:pct(count,topics.length)})}return vals}
function renderResources(){const q=(window.resourceQuery||'').toLowerCase(),type=window.resourceType||'all',track=window.resourceTrack||'all';const rows=[...resources,...state.customResources].filter(r=>(type==='all'||r.type===type)&&(track==='all'||r.track===track)&&(!q||`${r.title} ${r.provider} ${r.topic} ${r.description}`.toLowerCase().includes(q)));return `${headerKicker('Resource library','CURATED FROM YOUR ROADMAP',`<button class="button ghost" data-action="add-resource">＋ Add a resource</button>`)}<section class="library-intro"><div><span class="eyebrow">LEARN · PRACTICE · REFERENCE</span><h2>Good resources. Clear next steps.</h2><p>Primary links and topic guides from the source conversation, organized to make your next study session easy to start.</p></div><div class="resource-count"><b>${rows.length}</b><span>resources</span></div></section><div class="filter-bar library-filters"><label class="filter-search">⌕ <input id="resource-search" placeholder="Find a resource…" value="${esc(window.resourceQuery||'')}"></label><select id="resource-track"><option value="all">All tracks</option>${tracks.map(t=>`<option value="${esc(t.title)}" ${(track===t.title?'selected':'')}>${esc(t.title)}</option>`).join('')}</select><select id="resource-type"><option value="all">All types</option>${['Course','Documentation','Tutorial','Book','Lab','Tool','Reference'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="resource-grid">${rows.map(resourceCard).join('')||empty('⌕','No resources match','Try another search or filter.')}</div><div class="source-note"><span>ⓘ</span><p>Resource links are drawn from the shared roadmap. Book entries without a link are intentionally unlinked; confirm an edition before purchase. Provider access and course pricing can change.</p></div>`}
function resourceCard(r){const bookmarked=state.bookmarkedResources.includes(r.id);const ids=topics.filter(t=>t.title.toLowerCase().includes((r.topic||'').toLowerCase())||t.moduleTitle.toLowerCase().includes((r.topic||'').toLowerCase())).slice(0,3);return `<article class="resource-card"><div class="resource-card-top"><span class="resource-type">${esc(r.type)}</span><button class="bookmark-control ${bookmarked?'bookmarked':''}" data-bookmark-resource="${r.id}" aria-label="Bookmark ${esc(r.title)}">${bookmarked?'★':'☆'}</button></div><span class="resource-provider">${esc(r.provider||'Resource')}</span><h3>${esc(r.title)}</h3><p>${esc(r.description||`Recommended for ${r.topic||'your learning roadmap'}.`)}</p><div class="resource-meta"><span>${esc(r.track)}</span><span>${esc(r.level)}</span></div><div class="resource-card-foot">${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open resource <span>↗</span></a>`:`<span class="unlinked">No direct link in source</span>`}${ids.length?`<button data-topic="${ids[0].id}" class="resource-topic">Related topic →</button>`:''}</div></article>`}
function renderNotes(){const q=(window.noteQuery||'').toLowerCase(),cat=window.noteCategory||'all',sort=window.noteSort||'updated';let notes=[...state.notes].filter(n=>(cat==='all'||n.category===cat)&&(!q||`${n.title} ${n.content} ${n.tags.join(' ')} ${n.category}`.toLowerCase().includes(q)));notes.sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):b.updatedAt.localeCompare(a.updatedAt));const pinned=state.notes.filter(n=>n.pinned);return `${headerKicker('Notes & knowledge base','SAVE WHAT MATTERS',`<button class="button primary" data-action="new-note">＋ Create a note</button>`)}<section class="notes-hero"><div><span class="eyebrow">YOUR PERSONAL REFERENCE</span><h2>Make learning stick.</h2><p>Capture the commands, explanations and questions you’ll want to find again.</p></div><div class="notes-hero-stats"><div><b>${state.notes.length}</b><span>Notes</span></div><div><b>${pinned.length}</b><span>Pinned</span></div><div><b>${state.notes.filter(n=>n.reviewLater).length}</b><span>Review later</span></div></div></section><div class="notes-tools"><label class="filter-search">⌕ <input id="notes-search" placeholder="Search title, content or tags…" value="${esc(window.noteQuery||'')}"></label><select id="notes-category"><option value="all">All categories</option>${categories().map(c=>`<option ${cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="notes-sort"><option value="updated">Recently edited</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option></select><button class="button ghost" data-action="export-notes">Export notes</button></div>${pinned.length?`<div class="section-row compact"><div><span class="eyebrow">KEEP CLOSE</span><h2>Pinned notes</h2></div></div><div class="note-grid pinned-notes">${pinned.map(noteCard).join('')}</div>`:''}<div class="section-row compact"><div><span class="eyebrow">KNOWLEDGE BASE</span><h2>${cat==='all'?'All notes':esc(cat)}</h2></div><span class="muted-caption">${notes.length} ${notes.length===1?'note':'notes'}</span></div><div class="note-grid">${notes.length?notes.map(noteCard).join(''):empty('▤','No notes here yet','Create a note to save a concept, command or question.')}</div>`}
function categories(){return [...new Set(['Cybersecurity','IAM and Identity Engineering','Artificial Intelligence','AI Security','Projects and Labs','Interview Preparation','Commands and Code Snippets','Troubleshooting','Important Concepts','General Notes',...(state.settings.categories||[]),...state.notes.map(n=>n.category)])]}
function noteCard(n){const linked=topicById[n.topicId];return `<article class="note-card"><div class="note-card-top"><span class="note-category">${esc(n.category)}</span><div><button class="mini-icon ${n.favorite?'bookmarked':''}" data-note-action="favorite" data-id="${n.id}" aria-label="Favorite note">${n.favorite?'★':'☆'}</button><button class="mini-icon ${n.pinned?'bookmarked':''}" data-note-action="pin" data-id="${n.id}" aria-label="Pin note">⌖</button><button class="mini-icon" data-note-action="review" data-id="${n.id}" aria-label="Review later">${n.reviewLater?'↻':'◷'}</button></div></div><button class="note-card-title" data-edit-note="${n.id}">${esc(n.title)}</button><p>${esc(n.content.slice(0,180)||'No content yet.')}${n.content.length>180?'…':''}</p>${n.tags.length?`<div class="tag-list">${n.tags.map(x=>`<span>#${esc(x)}</span>`).join('')}</div>`:''}<div class="note-card-foot"><span>${dateLabel(n.updatedAt.slice(0,10))} · ${new Date(n.updatedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</span>${linked?`<button data-topic="${linked.id}">↗ ${esc(linked.title)}</button>`:''}</div></article>`}
function renderPlanner(){const sessions=[...state.sessions].sort((a,b)=>a.date.localeCompare(b.date)),upcoming=sessions.filter(s=>s.date>=today()&&s.status!=='Done'),overdue=sessions.filter(s=>s.date<today()&&s.status!=='Done'),complete=sessions.filter(s=>s.status==='Done');return `${headerKicker('Study planner','MAKE TIME FOR LEARNING',`<button class="button primary" data-action="new-session">＋ Schedule a session</button>`)}<section class="planner-hero"><div><span class="eyebrow">A FLEXIBLE 12-MONTH PATH</span><h2>Small steps. Real momentum.</h2><p>The source roadmap suggests 6–8 study hours each week. Adjust the goal to fit your life.</p></div><label class="goal-setting"><span>Weekly goal</span><input type="number" id="weekly-goal" min="1" max="60" value="${Number(state.settings.weeklyGoal)||6}"><b>hours</b></label></section><section class="plan-timeline"><div class="section-row"><div><span class="eyebrow">THE SUGGESTED SEQUENCE</span><h2>12-month roadmap</h2></div><span class="muted-caption">Flexible milestones, not deadlines</span></div><div class="months-grid">${plan12.map(p=>`<article class="month-card"><span class="month-number">${p.months}</span><div><b>${esc(p.title)}</b><p>${esc(p.topics)}</p><small><span>Milestone</span> ${esc(p.milestone)}</small></div></article>`).join('')}</div></section><section class="starter-plan panel"><div class="panel-heading"><div><span class="eyebrow">YOUR FIRST MONTH</span><h2>30-day starter plan</h2></div><span class="muted-caption">Edit by scheduling tasks when they suit you</span></div><div class="starter-weeks">${plan30.map(w=>`<article><h3>${esc(w.week)}</h3>${w.items.map((it,i)=>{const id=`d30-${w.week.split(' ')[1]}-${i}`,done=state.progress[id]?.status==='Completed';return `<label class="starter-task ${done?'done':''}"><input type="checkbox" data-plan-check="${id}" ${done?'checked':''}><span>${esc(it)}</span><button type="button" data-action="schedule-plan" data-title="${esc(it)}" aria-label="Schedule ${esc(it)}">＋</button></label>`}).join('')}</article>`).join('')}</div></section><div class="planner-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">NEXT UP</span><h2>Upcoming sessions</h2></div><span class="count-pill">${upcoming.length}</span></div>${upcoming.length?upcoming.map(sessionRow).join(''):empty('▦','No sessions planned','Pick a topic and reserve a little time for it.')}</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">NEEDS A NEW DATE</span><h2>Overdue sessions</h2></div><span class="count-pill warm">${overdue.length}</span></div>${overdue.length?overdue.map(sessionRow).join(''):empty('✓','You’re all caught up','Any unfinished session will show here.')}</section></div><section class="panel session-list"><div class="panel-heading"><div><span class="eyebrow">YOUR PLAN</span><h2>All study sessions</h2></div><span class="muted-caption">${complete.length} completed · ${sessions.length} total</span></div>${sessions.length?sessions.map(sessionRow).join(''):empty('◷','Your schedule is open','Add a topic or project session above.')}</section>`}
function sessionRow(s){const t=topicById[s.topicId],isOver=s.date<today()&&s.status!=='Done';return `<div class="session-row"><span class="session-date ${isOver?'overdue':''}"><b>${new Date(`${s.date}T12:00:00`).getDate()}</b><small>${new Date(`${s.date}T12:00:00`).toLocaleDateString('en-US',{month:'short'})}</small></span><div class="session-copy"><b>${esc(s.title||t?.title||'Study session')}</b><small>${dateLabel(s.date,{weekday:'long'})} · ${esc(s.time||'Any time')} · ${s.hours}h${t?` · ${esc(t.moduleTitle)}`:''}</small></div>${s.status==='Done'?`<span class="status complete">Done · ${Number(s.actualHours)||Number(s.hours)||0}h</span>`:`<button class="button small ghost" data-session-action="done" data-id="${s.id}">Mark done</button>`}<button class="mini-icon" data-session-action="edit" data-id="${s.id}" aria-label="Reschedule">↗</button><button class="mini-icon danger" data-session-action="delete" data-id="${s.id}" aria-label="Delete session">×</button></div>`}
function renderProjects(){return `${headerKicker('Projects & labs','LEARN BY BUILDING',`<button class="button ghost" data-action="add-project">＋ Add a project</button>`)}<section class="project-intro"><div><span class="eyebrow">FROM THEORY TO EVIDENCE</span><h2>Build. Test. Document.</h2><p>Five guided projects from your roadmap. Each one becomes proof of what you can design and secure.</p></div><div class="safety-callout"><span>ⓘ</span><p><b>Practice safely</b> Only test systems you own or have explicit authorization to assess. Use synthetic data and isolated lab environments for red-team exercises.</p></div></section><div class="projects-grid">${tracks.find(t=>t.id==='projects').modules.map((m,i)=>projectCard(m,i)).join('')}</div>`}
function projectCard(m,i){const done=m.children.filter(x=>statusOf(x.id)==='Completed').length,all=m.children.length,per=pct(done,all),details=state.projectDetails[m.id]||{};return `<article class="project-card"><div class="project-card-head"><span class="project-number">0${i+1}</span><span class="project-level ${m.level.toLowerCase()}">${m.level}</span><button class="bookmark-control ${state.bookmarkedTopics.includes(m.id)?'bookmarked':''}" data-bookmark-project="${m.id}" aria-label="Bookmark project">${state.bookmarkedTopics.includes(m.id)?'★':'☆'}</button></div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><div class="project-progress-line"><span>Project progress</span><b>${per}%</b></div>${progressBar(per,'teal')}<div class="project-meta"><span>◈ ${all} milestones</span><span>◷ ${m.children.reduce((n,x)=>n+x.hours,0)}h estimated</span></div><details class="project-details"><summary>View milestones & workspace</summary><div class="milestone-list">${m.children.map(x=>`<label><input type="checkbox" data-topic-check="${x.id}" ${statusOf(x.id)==='Completed'?'checked':''}><span>${esc(x.title)}<small>${x.hours}h · ${esc(x.desc)}</small></span></label>`).join('')}</div><label class="field-label">Repository URL<input class="project-repo" data-project-field="repo" data-project="${m.id}" type="url" placeholder="https://github.com/you/project" value="${esc(details.repo||'')}"></label><label class="field-label">Lessons learned<textarea class="project-lessons" data-project-field="lessons" data-project="${m.id}" rows="3" placeholder="What did you learn?">${esc(details.lessons||'')}</textarea></label><button class="button small ghost" data-action="project-note" data-project="${m.id}">Write a linked note</button></details></article>`}
function customProjectCard(x,i){return `<article class="project-card"><div class="project-card-head"><span class="project-number">＋</span><span class="project-level">CUSTOM</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description||'Custom project')}</p><button class="button small ghost" data-topic="${x.id}">Open details →</button></article>`}
function renderBookmarks(){const bt=state.bookmarkedTopics.map(id=>topicById[id]||tracks.find(t=>t.id===id)?.modules.find(m=>m.id===id)).filter(Boolean),br=state.bookmarkedResources.map(id=>resourceById[id]||state.customResources.find(r=>r.id===id)).filter(Boolean),bn=state.notes.filter(n=>n.favorite||n.pinned);return `${headerKicker('Bookmarks','YOUR QUICK REFERENCE',`<button class="button ghost" data-action="export">↧ Export backup</button>`)}<section class="bookmark-summary"><div><span class="eyebrow">SAVED FOR LATER</span><h2>Your important things, all together.</h2></div><div class="bookmark-counts"><span><b>${bt.length}</b> Topics</span><span><b>${br.length}</b> Resources</span><span><b>${bn.length}</b> Notes</span></div></section><section class="panel saved-section"><div class="panel-heading"><div><span class="eyebrow">LEARNING ROADMAP</span><h2>Saved topics</h2></div></div>${bt.length?bt.map(t=>`<div class="saved-row"><span class="saved-glyph">⌘</span><button data-topic="${t.id}"><b>${esc(t.title)}</b><small>${esc(t.trackTitle||t.description||'Learning track')} · ${esc(t.moduleTitle||'')}</small></button><button class="mini-icon" data-unbookmark-topic="${t.id}" aria-label="Remove bookmark">★</button></div>`).join(''):empty('☆','No saved topics','Bookmark topics in your roadmap for quick access.')}</section><section class="panel saved-section"><div class="panel-heading"><div><span class="eyebrow">LEARNING LIBRARY</span><h2>Saved resources</h2></div><button class="subtle-link" data-view="resources">Browse resources →</button></div>${br.length?br.map(r=>`<div class="saved-row"><span class="saved-glyph">↗</span><div><b>${esc(r.title)}</b><small>${esc(r.provider)} · ${esc(r.topic)}</small></div>${r.url?`<a class="subtle-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:''}<button class="mini-icon" data-bookmark-resource="${r.id}" aria-label="Remove bookmark">★</button></div>`).join(''):empty('☆','No saved resources','Save useful references from the resource library.')}</section><section class="panel saved-section"><div class="panel-heading"><div><span class="eyebrow">KNOWLEDGE BASE</span><h2>Favorites & pinned notes</h2></div><button class="subtle-link" data-view="notes">Open notes →</button></div>${bn.length?bn.map(noteRow).join(''):empty('▤','No saved notes','Pin or favorite a note to keep it close.')}</section>`}
function noteRow(n){return `<div class="note-row"><span>▤</span><button data-edit-note="${n.id}"><b>${esc(n.title)}</b><small>${esc(n.category)} · Updated ${dateLabel(n.updatedAt.slice(0,10))}</small></button><span class="note-flags">${n.pinned?'⌖ ':''}${n.favorite?'★ ':''}${n.reviewLater?'↻':''}</span></div>`}
function renderSettings(){return `${headerKicker('Settings','MAKE IT YOURS')}<section class="settings-grid"><article class="panel settings-card"><span class="eyebrow">APPEARANCE</span><h2>Theme</h2><p>Follow your device, or choose a permanent look for this workspace.</p><div class="segmented">${['system','light','dark'].map(x=>`<button class="${state.settings.theme===x?'chosen':''}" data-setting-theme="${x}">${x==='system'?'◐ System':x==='light'?'☼ Light':'◐ Dark'}</button>`).join('')}</div></article><article class="panel settings-card"><span class="eyebrow">STUDY RHYTHM</span><h2>Weekly study goal</h2><p>Your planner uses this as a flexible target, not a deadline.</p><label class="field-label">Hours per week<input type="number" id="settings-weekly-goal" min="1" max="60" value="${Number(state.settings.weeklyGoal)||6}"></label></article><article class="panel settings-card"><span class="eyebrow">YOUR INTERESTS</span><h2>Preferred learning tracks</h2><p>Choose what you’d like to focus on. Your curriculum stays complete.</p><div class="track-preferences">${tracks.map(t=>`<label><input type="checkbox" data-preferred-track="${t.id}" ${(state.settings.preferredTracks||[]).includes(t.id)?'checked':''}><span>${t.icon} ${esc(t.title)}</span></label>`).join('')}</div></article><article class="panel settings-card"><span class="eyebrow">DATA & BACKUP</span><h2>Your learning data</h2><p>Progress, notes and settings stay in this browser. Export a copy before clearing browser data.</p><div class="button-stack"><button class="button ghost" data-action="export">↧ Export full backup (.json)</button><button class="button ghost" data-action="export-notes">▤ Export notes (.md)</button><button class="button ghost" data-action="import">↥ Restore from backup</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><small class="local-warning">Local browser storage does not sync across devices. Keep a backup in a place you control.</small></article><article class="panel settings-card"><span class="eyebrow">CURRICULUM PREFERENCES</span><h2>Default difficulty</h2><p>Choose a starting filter for the roadmap.</p><select id="default-difficulty"><option value="all">All levels</option>${['Beginner','Intermediate','Advanced'].map(x=>`<option ${state.settings.defaultDifficulty===x?'selected':''}>${x}</option>`).join('')}</select></article><article class="panel settings-card"><span class="eyebrow">RECOVERY</span><h2>Reset learning progress</h2><p>This clears completion states, logged time and study sessions. Notes and bookmarks stay intact.</p><button class="button danger-outline" data-action="reset-progress">Reset progress…</button></article></section><section class="panel categories-settings"><div class="panel-heading"><div><span class="eyebrow">PERSONAL ORGANIZATION</span><h2>Custom note categories & tags</h2></div></div><div class="custom-chip-list">${categories().slice(10).map(c=>`<span>${esc(c)} <button data-remove-category="${esc(c)}" aria-label="Remove category">×</button></span>`).join('')}${(state.settings.customTags||[]).map(c=>`<span class="tag-chip">#${esc(c)} <button data-remove-tag="${esc(c)}" aria-label="Remove tag">×</button></span>`).join('')}</div><form id="custom-term-form" class="inline-form"><input id="custom-term" placeholder="New category or tag" required><select id="custom-term-type"><option value="category">Category</option><option value="tag">Tag</option></select><button class="button small primary">Add</button></form></section>`}
function renderModal(){if(!modal)return '';if(modal.type==='topic')return topicModal(modal.id);if(modal.type==='note')return noteModal(modal.id);if(modal.type==='session')return sessionModal(modal.id,modal.preset);if(modal.type==='confirm')return `<div class="modal-backdrop" data-close-modal><section class="dialog-card small-dialog" role="dialog" aria-modal="true"><div class="dialog-top"><span class="dialog-icon warn">!</span><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><h2>${esc(modal.title)}</h2><p>${esc(modal.message)}</p><div class="dialog-actions"><button class="button ghost" data-action="close-modal">Cancel</button><button class="button danger-solid" data-action="confirm-action">${esc(modal.confirm||'Confirm')}</button></div></section></div>`;if(modal.type==='add-topic')return addTopicModal();if(modal.type==='add-resource')return addResourceModal();if(modal.type==='add-project')return addProjectModal();return ''}
function topicModal(id){const t=topicById[id]||state.customTopics.find(x=>x.id===id);if(!t)return '';const p=state.progress[id]||{},rs=resourcesFor(t.resources||[]),deps=(t.dependencies||[]).map(x=>topicById[x]).filter(Boolean),related=state.notes.filter(n=>n.topicId===id);return `<div class="modal-backdrop" data-close-modal><section class="dialog-card topic-dialog" role="dialog" aria-modal="true" aria-labelledby="topic-modal-title"><div class="dialog-top"><span class="eyebrow">${esc(t.trackTitle||'CUSTOM TOPIC')} ${t.moduleTitle?`· ${esc(t.moduleTitle)}`:''}</span><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="topic-modal-heading"><span class="track-icon ${trackById(t.trackId)?.color||'blue'}">${trackById(t.trackId)?.icon||'⌘'}</span><div><h2 id="topic-modal-title">${esc(t.title)}</h2><p>${esc(t.desc||'Add your own learning notes and objective for this topic.')}</p></div><button class="bookmark-control ${state.bookmarkedTopics.includes(id)?'bookmarked':''}" data-bookmark-topic="${id}" aria-label="Bookmark topic">${state.bookmarkedTopics.includes(id)?'★':'☆'}</button></div><div class="topic-modal-meta"><span>${t.level}</span><span>◷ ${t.hours||1}h estimated</span>${deps.length?`<span>Prerequisite: ${deps.map(d=>esc(d.title)).join(', ')}</span>`:''}</div><div class="topic-fields"><label class="field-label">Status<select data-modal-status="${id}">${['Not Started','In Progress','Completed'].map(v=>`<option ${statusOf(id)===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field-label">Priority<select data-modal-priority="${id}">${['Low','Medium','High'].map(v=>`<option ${(p.priority||'Medium')===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field-label">Target date<input data-modal-target="${id}" type="date" value="${esc(p.targetDate||'')}"></label><label class="field-label">Actual study time (hours)<input data-modal-actual="${id}" type="number" min="0" step="0.25" value="${Number(p.actualHours)||0}"></label></div>${t.resources?.length?`<div class="modal-section"><h3>Recommended resources</h3><div class="related-resource-list">${rs.map(r=>`<div><span>↗</span><span><b>${esc(r.title)}</b><small>${esc(r.provider)} · ${esc(r.type)}</small></span>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open</a>`:''}</div>`).join('')}</div></div>`:''}<div class="modal-section"><div class="modal-section-title"><h3>Learning notes</h3><button class="subtle-link" data-action="topic-note" data-topic="${id}">${related.length?'Open note':'＋ Create linked note'}</button></div><textarea class="topic-personal-notes" data-modal-notes="${id}" rows="4" placeholder="What do you want to remember about this topic?">${esc(p.notes||'')}</textarea><small class="autosave-label">Changes save automatically in this browser.</small></div><div class="dialog-actions"><button class="button ghost" data-action="close-modal">Close</button><button class="button primary" data-action="save-topic" data-id="${id}">Save topic</button></div></section></div>`}
function noteModal(id){const n=state.notes.find(x=>x.id===id)||{id:'',title:'',content:'',category:'General Notes',tags:[],topicId:'',pinned:false,favorite:false,reviewLater:false};return `<div class="modal-backdrop" data-close-modal><section class="dialog-card note-dialog" role="dialog" aria-modal="true" aria-labelledby="note-modal-title"><div class="dialog-top"><span class="eyebrow">${id?'EDIT NOTE':'NEW NOTE'} · AUTOSAVED LOCALLY</span><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><div class="note-editor-title"><input id="note-title" placeholder="Give this note a clear title…" value="${esc(n.title)}" aria-label="Note title"><span id="note-save-state">${id?'Saved':'Draft'}</span></div><div class="format-toolbar"><button data-format="## ">H2</button><button data-format="**|**">B</button><button data-format="*|*"><i>I</i></button><button data-format="- ">• List</button><button data-format="1. ">1. List</button><button data-format="- [ ] ">☐ Task</button><button data-format="codeblock">&lt;/&gt; Code</button><button data-format="[|](https://)">↗ Link</button><span>Markdown supported</span></div><textarea id="note-content" placeholder="Start writing. Markdown headings, lists, links and code blocks are supported…" rows="12">${esc(n.content)}</textarea><div class="note-editor-grid"><label class="field-label">Category<select id="note-category">${categories().map(c=>`<option ${n.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field-label">Linked topic<select id="note-topic"><option value="">No linked topic</option>${topics.map(t=>`<option value="${t.id}" ${n.topicId===t.id?'selected':''}>${esc(t.trackTitle)} · ${esc(t.title)}</option>`).join('')}</select></label><label class="field-label">Tags<input id="note-tags" placeholder="Separate tags with commas" value="${esc((n.tags||[]).join(', '))}"></label></div><div class="note-flags-editor"><label><input type="checkbox" id="note-pin" ${n.pinned?'checked':''}> Pin</label><label><input type="checkbox" id="note-favorite" ${n.favorite?'checked':''}> Favorite</label><label><input type="checkbox" id="note-review" ${n.reviewLater?'checked':''}> Review later</label></div><div class="dialog-actions">${id?`<button class="button danger-outline" data-action="delete-note" data-id="${id}">Delete note</button>`:''}<span class="autosave-label">${id?`Created ${dateLabel(n.createdAt.slice(0,10))} · Edited ${dateLabel(n.updatedAt.slice(0,10))}`:'Your draft saves when you save or close.'}</span><button class="button primary" data-action="save-note" data-id="${id}">Save note</button></div></section></div>`}
function sessionModal(id,preset=''){const old=state.sessions.find(x=>x.id===id)||{id:'',title:preset||'',date:today(),time:'09:00',hours:1,actualHours:0,topicId:'',status:'Planned'};return `<div class="modal-backdrop" data-close-modal><section class="dialog-card small-dialog" role="dialog" aria-modal="true"><div class="dialog-top"><span class="eyebrow">${id?'EDIT STUDY SESSION':'PLAN A STUDY SESSION'}</span><button class="modal-close" data-action="close-modal">×</button></div><h2>${id?'Update your session':'Make some room to learn.'}</h2><form id="session-form" data-id="${id}"><label class="field-label">Session title<input id="session-title" value="${esc(old.title)}" placeholder="e.g. Practice OAuth flows" required></label><label class="field-label">Link to topic or project<select id="session-topic"><option value="">No linked topic</option>${topics.map(t=>`<option value="${t.id}" ${old.topicId===t.id?'selected':''}>${esc(t.trackTitle)} · ${esc(t.title)}</option>`).join('')}</select></label><div class="form-two"><label class="field-label">Date<input id="session-date" type="date" value="${esc(old.date)}" required></label><label class="field-label">Start time<input id="session-time" type="time" value="${esc(old.time||'09:00')}"></label></div><div class="form-two"><label class="field-label">Planned hours<input id="session-hours" type="number" min="0.25" max="24" step="0.25" value="${Number(old.hours)||1}" required></label><label class="field-label">Actual hours${old.status==='Done'?`<input id="session-actual" type="number" min="0" step="0.25" value="${Number(old.actualHours)||Number(old.hours)||1}">`:`<span class="form-help">Logged when marked complete</span>`}</label></div><div class="dialog-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button primary">Save session</button></div></form></section></div>`}
function addTopicModal(){return `<div class="modal-backdrop" data-close-modal><section class="dialog-card small-dialog" role="dialog" aria-modal="true"><div class="dialog-top"><span class="eyebrow">CUSTOM CURRICULUM</span><button class="modal-close" data-action="close-modal">×</button></div><h2>Add a learning topic</h2><form id="add-topic-form"><label class="field-label">Topic title<input id="custom-topic-title" required></label><label class="field-label">Track<select id="custom-topic-track">${tracks.filter(t=>t.id!=='projects').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><label class="field-label">Module name<input id="custom-topic-module" value="My topics" required></label><label class="field-label">Difficulty<select id="custom-topic-level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label><label class="field-label">Estimated hours<input id="custom-topic-hours" type="number" min="0.25" step="0.25" value="1"></label><label class="field-label">Description<textarea id="custom-topic-desc" rows="2"></textarea></label><div class="dialog-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button primary">Add topic</button></div></form></section></div>`}
function addResourceModal(){return `<div class="modal-backdrop" data-close-modal><section class="dialog-card small-dialog" role="dialog" aria-modal="true"><div class="dialog-top"><span class="eyebrow">CUSTOM RESOURCE</span><button class="modal-close" data-action="close-modal">×</button></div><h2>Add a resource</h2><form id="add-resource-form"><label class="field-label">Title<input id="custom-resource-title" required></label><label class="field-label">URL<input id="custom-resource-url" type="url" placeholder="https://…"></label><label class="field-label">Provider<input id="custom-resource-provider"></label><label class="field-label">Type<select id="custom-resource-type">${['Course','Documentation','Tutorial','Book','Lab','Tool','Reference'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field-label">Learning track<select id="custom-resource-track">${tracks.map(t=>`<option>${esc(t.title)}</option>`).join('')}</select></label><label class="field-label">Related topic<input id="custom-resource-topic"></label><label class="field-label">Description<textarea id="custom-resource-desc" rows="2"></textarea></label><div class="dialog-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button primary">Add resource</button></div></form></section></div>`}
function addProjectModal(){return `<div class="modal-backdrop" data-close-modal><section class="dialog-card small-dialog" role="dialog" aria-modal="true"><div class="dialog-top"><span class="eyebrow">CUSTOM PROJECT</span><button class="modal-close" data-action="close-modal">×</button></div><h2>Add a project</h2><form id="add-project-form"><label class="field-label">Project name<input id="custom-project-title" required></label><label class="field-label">Track<select id="custom-project-track">${tracks.filter(t=>t.id!=='projects').map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><label class="field-label">Overview<textarea id="custom-project-desc" rows="3" required></textarea></label><div class="dialog-actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button primary">Add project</button></div></form></section></div>`}
function bind(){document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;mobileMenu=false;render()});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=e=>{e.stopPropagation();modal={type:'topic',id:el.dataset.topic};if(topicById[el.dataset.topic]){state.progress[el.dataset.topic]={...(state.progress[el.dataset.topic]||{}),lastViewedAt:new Date().toISOString()};save()}render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>handleAction(e,el));document.querySelectorAll('[data-topic-check]').forEach(el=>el.onchange=()=>setStatus(el.dataset.topicCheck,el.checked?'Completed':(statusOf(el.dataset.topicCheck)==='Completed'?'Not Started':statusOf(el.dataset.topicCheck))));document.querySelectorAll('[data-topic-status]').forEach(el=>el.onchange=()=>setStatus(el.dataset.topicStatus,el.value));document.querySelectorAll('[data-bookmark-topic]').forEach(el=>el.onclick=()=>toggleArray('bookmarkedTopics',el.dataset.bookmarkTopic));document.querySelectorAll('[data-bookmark-project]').forEach(el=>el.onclick=()=>toggleArray('bookmarkedTopics',el.dataset.bookmarkProject));document.querySelectorAll('[data-unbookmark-topic]').forEach(el=>el.onclick=()=>toggleArray('bookmarkedTopics',el.dataset.unbookmarkTopic));document.querySelectorAll('[data-bookmark-resource]').forEach(el=>el.onclick=()=>toggleArray('bookmarkedResources',el.dataset.bookmarkResource));document.querySelectorAll('[data-note-action]').forEach(el=>el.onclick=()=>noteFlag(el.dataset.id,el.dataset.noteAction));document.querySelectorAll('[data-edit-note]').forEach(el=>el.onclick=()=>{modal={type:'note',id:el.dataset.editNote};render()});document.querySelectorAll('[data-close-modal]').forEach(el=>el.onclick=e=>{if(e.target===el){modal=null;render()}});document.querySelectorAll('[data-session-action]').forEach(el=>el.onclick=()=>sessionAction(el.dataset.id,el.dataset.sessionAction));document.querySelectorAll('[data-setting-theme]').forEach(el=>el.onclick=()=>{state.settings.theme=el.dataset.settingTheme;save();render()});document.querySelectorAll('[data-preferred-track]').forEach(el=>el.onchange=()=>{let p=new Set(state.settings.preferredTracks||[]);el.checked?p.add(el.dataset.preferredTrack):p.delete(el.dataset.preferredTrack);state.settings.preferredTracks=[...p];save()});document.querySelectorAll('[data-remove-category]').forEach(el=>el.onclick=()=>{state.settings.categories=state.settings.categories.filter(x=>x!==el.dataset.removeCategory);save();render()});document.querySelectorAll('[data-remove-tag]').forEach(el=>el.onclick=()=>{state.settings.customTags=state.settings.customTags.filter(x=>x!==el.dataset.removeTag);save();render()});document.querySelectorAll('[data-project-field]').forEach(el=>el.onchange=()=>{const p=state.projectDetails[el.dataset.project]||{};p[el.dataset.projectField]=el.value;state.projectDetails[el.dataset.project]=p;save()});document.querySelectorAll('[data-plan-check]').forEach(el=>el.onchange=()=>{const id=el.dataset.planCheck;const p=state.progress[id]||{};p.status=el.checked?'Completed':'Not Started';if(el.checked)p.completedAt=new Date().toISOString();else delete p.completedAt;state.progress[id]=p;save();render()});bindFilters();bindForms();bindNoteEditor();const gs=document.querySelector('#global-search');if(gs){gs.oninput=()=>{window.globalQuery=gs.value;showGlobalSearch(gs.value)};gs.onkeydown=e=>{if(e.key==='Enter'){const first=document.querySelector('.search-hit');if(first)first.click()}if(e.key==='Escape'){window.globalQuery='';gs.value='';showGlobalSearch('')}}}document.querySelectorAll('[data-session-action="done"]').forEach(el=>{});}
function handleAction(e,el){const a=el.dataset.action;switch(a){case'menu':mobileMenu=!mobileMenu;render();break;case'theme':state.settings.theme=state.settings.theme==='dark'?'light':state.settings.theme==='light'?'dark':(getTheme()==='dark'?'light':'dark');save();render();break;case'continue':{const f=currentFocus();if(f){modal={type:'topic',id:f.id};render()}else{view='roadmap';render()}break}case'remove-continue':state.hiddenContinue=[...new Set([...(state.hiddenContinue||[]),el.dataset.id])];save();render();toast('Removed from Continue Learning. Topic status and progress are unchanged.');break;case'restore-continue':state.hiddenContinue=[];save();render();toast('Skipped topics restored to Continue Learning.');break;case'open-track':{filters.track=el.dataset.track;view='roadmap';render();break}case'toggle-track':expanded.has(el.dataset.track)?expanded.delete(el.dataset.track):expanded.add(el.dataset.track);render();break;case'toggle-module':expanded.has(el.dataset.module)?expanded.delete(el.dataset.module):expanded.add(el.dataset.module);render();break;case'expand-all':if(expanded.size>1){expanded.clear()}else tracks.forEach(t=>{expanded.add(t.id);t.modules.forEach(m=>expanded.add(m.id))});render();break;case'reset-filters':filters={...filters,query:'',track:'all',status:'all',difficulty:'all',priority:'all',sort:'order'};render();break;case'new-note':modal={type:'note',id:''};render();break;case'topic-note':case'project-note':{const id=el.dataset.topic||el.dataset.project,n=state.notes.find(x=>x.topicId===id);modal={type:'note',id:n?.id||'',presetTopic:id};render();break}case'new-session':modal={type:'session',id:''};render();break;case'schedule-plan':modal={type:'session',id:'',preset:el.dataset.title};render();break;case'export':exportBackup();break;case'export-notes':exportNotes();break;case'import':document.querySelector('#import-file')?.click();break;case'reset-progress':modal={type:'confirm',title:'Reset learning progress?',message:'Topic statuses, progress history, logged hours and study sessions will be removed. Your notes, projects, resources and bookmarks will stay.',confirm:'Reset progress',callback:resetProgress};render();break;case'confirm-action':if(modal?.callback)modal.callback();modal=null;render();break;case'close-modal':modal=null;render();break;case'save-topic':saveTopic(el.dataset.id);break;case'delete-note':deleteNote(el.dataset.id);break;case'toggle-detail':state.settings.detailedAnalytics=state.settings.detailedAnalytics===false;save();render();break;case'add-topic':modal={type:'add-topic'};render();break;case'add-resource':modal={type:'add-resource'};render();break;case'add-project':modal={type:'add-project'};render();break;case'reset':resetProgress();break;}}
function setStatus(id,status){if(!state.progress[id])state.progress[id]={};const p=state.progress[id];p.status=status;if(status==='Completed'){p.completedAt=p.completedAt||new Date().toISOString()}else delete p.completedAt;save();render();toast(status==='Completed'?'Topic completed. Progress updated.':'Topic status updated.')}
function toggleArray(key,id){state[key]=state[key]||[];state[key].includes(id)?state[key]=state[key].filter(x=>x!==id):state[key].push(id);save();render()}
function saveTopic(id){const p=state.progress[id]||{};const status=document.querySelector(`[data-modal-status="${id}"]`)?.value||statusOf(id);p.status=status;p.priority=document.querySelector(`[data-modal-priority="${id}"]`)?.value||'Medium';p.targetDate=document.querySelector(`[data-modal-target="${id}"]`)?.value||'';p.actualHours=Number(document.querySelector(`[data-modal-actual="${id}"]`)?.value)||0;p.notes=document.querySelector(`[data-modal-notes="${id}"]`)?.value||'';if(status==='Completed')p.completedAt=p.completedAt||new Date().toISOString();else delete p.completedAt;state.progress[id]=p;save();modal=null;render();toast('Topic saved.')}
function bindFilters(){const map=[['roadmap-search','query'],['filter-track','track'],['filter-status','status'],['filter-difficulty','difficulty'],['filter-priority','priority'],['filter-sort','sort']];map.forEach(([id,key])=>{const el=document.getElementById(id);if(el){el.oninput=el.onchange=()=>{filters[key]=el.value;renderPreserveFocus(id)}}});const rq=document.getElementById('resource-search');if(rq)rq.oninput=()=>{window.resourceQuery=rq.value;renderPreserveFocus('resource-search')};const rt=document.getElementById('resource-track'),rty=document.getElementById('resource-type');if(rt)rt.onchange=()=>{window.resourceTrack=rt.value;render()};if(rty)rty.onchange=()=>{window.resourceType=rty.value;render()};const nq=document.getElementById('notes-search');if(nq)nq.oninput=()=>{window.noteQuery=nq.value;renderPreserveFocus('notes-search')};const nc=document.getElementById('notes-category'),ns=document.getElementById('notes-sort');if(nc)nc.onchange=()=>{window.noteCategory=nc.value;render()};if(ns)ns.onchange=()=>{window.noteSort=ns.value;render()}}
function renderPreserveFocus(id){const el=document.getElementById(id),v=el?.value,start=el?.selectionStart;render();const next=document.getElementById(id);if(next){next.focus();if(typeof start==='number'&&next.setSelectionRange)next.setSelectionRange(start,start)}}
function bindForms(){const sf=document.querySelector('#session-form');if(sf)sf.onsubmit=e=>{e.preventDefault();const id=sf.dataset.id||uid(),old=state.sessions.find(x=>x.id===id)||{};const s={...old,id,title:document.querySelector('#session-title').value.trim(),topicId:document.querySelector('#session-topic').value,date:document.querySelector('#session-date').value,time:document.querySelector('#session-time').value,hours:Number(document.querySelector('#session-hours').value),status:old.status||'Planned'};const actual=document.querySelector('#session-actual');if(actual)s.actualHours=Number(actual.value)||0;state.sessions=state.sessions.filter(x=>x.id!==id).concat(s);save();modal=null;render();toast('Study session saved.')};const at=document.querySelector('#add-topic-form');if(at)at.onsubmit=e=>{e.preventDefault();const tid=document.querySelector('#custom-topic-track').value,track=trackById(tid),modName=document.querySelector('#custom-topic-module').value.trim(),title=document.querySelector('#custom-topic-title').value.trim();let module=track.modules.find(m=>m.title===modName);if(!module){module={id:`custom-module-${uid()}`,title:modName,level:'Beginner',desc:'Custom module',dependencies:[],children:[]};track.modules.push(module)}const x={id:`custom-${uid()}`,title,level:document.querySelector('#custom-topic-level').value,hours:Number(document.querySelector('#custom-topic-hours').value)||1,desc:document.querySelector('#custom-topic-desc').value,resources:[],dependencies:[],type:'topic',trackId:tid,trackTitle:track.title,moduleId:module.id,moduleTitle:module.title};module.children.push(x);topics.push(x);topicById[x.id]=x;state.customTopics.push(x);save();modal=null;view='roadmap';expanded.add(tid);expanded.add(module.id);render();toast('Custom topic added.')};const ar=document.querySelector('#add-resource-form');if(ar)ar.onsubmit=e=>{e.preventDefault();state.customResources.push({id:`custom-resource-${uid()}`,title:document.querySelector('#custom-resource-title').value.trim(),url:document.querySelector('#custom-resource-url').value.trim(),provider:document.querySelector('#custom-resource-provider').value.trim(),type:document.querySelector('#custom-resource-type').value,track:document.querySelector('#custom-resource-track').value,topic:document.querySelector('#custom-resource-topic').value,description:document.querySelector('#custom-resource-desc').value,level:'Beginner'});save();modal=null;render();toast('Resource added.')};const ap=document.querySelector('#add-project-form');if(ap)ap.onsubmit=e=>{e.preventDefault();const id=`project-${uid()}`,title=document.querySelector('#custom-project-title').value.trim(),description=document.querySelector('#custom-project-desc').value,trackId=document.querySelector('#custom-project-track').value,track=tracks.find(t=>t.id==='projects'),milestones=['Define scope, objectives and prerequisites','Complete implementation tasks in an authorized environment','Document deliverables, tests and lessons learned'].map((title,i)=>({id:`${id}-milestone-${i+1}`,title,level:'Beginner',hours:1,desc:'Custom project milestone',resources:[],dependencies:[]})),x={id,title,description,trackId:'projects',moduleId:id,moduleTitle:title,isProject:true,level:'Custom',milestones};state.customTopics.push(x);hydrateCustomTopics();save();modal=null;render();toast('Project added with three trackable milestones.')};const cf=document.querySelector('#custom-term-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const v=document.querySelector('#custom-term').value.trim(),type=document.querySelector('#custom-term-type').value;if(type==='category'){state.settings.categories.push(v)}else state.settings.customTags.push(v.replace(/^#/,'').replace(/\s+/g,'-'));save();render()};const g=document.querySelector('#weekly-goal'),sg=document.querySelector('#settings-weekly-goal');[g,sg].filter(Boolean).forEach(x=>x.onchange=()=>{state.settings.weeklyGoal=Math.max(1,Math.min(60,Number(x.value)||6));save();render()});const dd=document.querySelector('#default-difficulty');if(dd)dd.onchange=()=>{state.settings.defaultDifficulty=dd.value;filters.difficulty=dd.value;save()};const imp=document.querySelector('#import-file');if(imp)imp.onchange=()=>importBackup(imp.files[0])}
function bindNoteEditor(){let timer;const saveDraft=()=>{clearTimeout(timer);const status=document.querySelector('#note-save-state');if(status)status.textContent='Saving…';timer=setTimeout(()=>{const title=document.querySelector('#note-title')?.value.trim()||'Untitled note',content=document.querySelector('#note-content')?.value||'',prior=state.notes.find(n=>n.id===modal?.id),now=new Date().toISOString(),id=modal?.id||uid();if(modal)modal.id=id;const n={...(prior||{}),id,title,content,category:document.querySelector('#note-category')?.value||'General Notes',tags:(document.querySelector('#note-tags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),topicId:document.querySelector('#note-topic')?.value||modal?.presetTopic||'',pinned:!!document.querySelector('#note-pin')?.checked,favorite:!!document.querySelector('#note-favorite')?.checked,reviewLater:!!document.querySelector('#note-review')?.checked,createdAt:prior?.createdAt||now,updatedAt:now};state.notes=state.notes.filter(x=>x.id!==id).concat(n);save();if(status)status.textContent='Saved locally'},500)};document.querySelectorAll('#note-title,#note-content,#note-tags,#note-category,#note-topic,#note-pin,#note-favorite,#note-review').forEach(el=>{el.addEventListener('input',saveDraft);el.addEventListener('change',saveDraft)});document.querySelectorAll('[data-format]').forEach(btn=>btn.onclick=()=>formatMarkdown(btn.dataset.format));document.querySelector('[data-action="save-note"]')?.addEventListener('click',()=>saveNote(modal?.id||'',modal?.presetTopic||''));}
function formatMarkdown(mark){const ta=document.querySelector('#note-content');if(!ta)return;const start=ta.selectionStart,end=ta.selectionEnd,sel=ta.value.slice(start,end),fmt=mark==='codeblock'?'\x60\x60\x60\n'+(sel||'code')+'\n\x60\x60\x60':mark.includes('|')?mark.replace('|',sel||'text').replace('|',''):mark+(sel||'text');ta.setRangeText(fmt,start,end,'end');ta.focus();const b=document.querySelector('#note-save-state');if(b)b.textContent='Unsaved draft'}
function saveNote(id='',presetTopic=''){const title=document.querySelector('#note-title')?.value.trim(),content=document.querySelector('#note-content')?.value||'';if(!title){document.querySelector('#note-title')?.focus();toast('Add a title to save this note.','error');return}const prior=state.notes.find(n=>n.id===id),now=new Date().toISOString(),topic=document.querySelector('#note-topic')?.value||presetTopic||'';const n={...(prior||{}),id:id||uid(),title,content,category:document.querySelector('#note-category')?.value||'General Notes',tags:(document.querySelector('#note-tags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),topicId:topic,pinned:!!document.querySelector('#note-pin')?.checked,favorite:!!document.querySelector('#note-favorite')?.checked,reviewLater:!!document.querySelector('#note-review')?.checked,createdAt:prior?.createdAt||now,updatedAt:now};state.notes=state.notes.filter(x=>x.id!==n.id).concat(n);save();modal=null;render();toast('Note saved locally.')}
function deleteNote(id){modal={type:'confirm',title:'Delete this note?',message:'This note will be removed from this browser. Export your notes first if you want to keep a copy.',confirm:'Delete note',callback:()=>{state.notes=state.notes.filter(x=>x.id!==id);save();modal=null;render();toast('Note deleted.')}};render()}
function noteFlag(id,key){const n=state.notes.find(x=>x.id===id);if(!n)return;const prop={favorite:'favorite',pin:'pinned',review:'reviewLater'}[key];n[prop]=!n[prop];n.updatedAt=new Date().toISOString();save();render()}
function sessionAction(id,key){const s=state.sessions.find(x=>x.id===id);if(!s)return;if(key==='done'){s.status='Done';s.actualHours=Number(s.actualHours)||Number(s.hours)||0;save();render();toast('Session completed. Time logged.')}else if(key==='edit'){modal={type:'session',id};render()}else if(key==='delete'){modal={type:'confirm',title:'Remove this study session?',message:'This will remove the session from your planner.',confirm:'Remove session',callback:()=>{state.sessions=state.sessions.filter(x=>x.id!==id);save();modal=null;render()}};render()}}
function resetProgress(){state.progress={};state.sessions=[];save();modal=null;render();toast('Learning progress has been reset.')}
function exportBackup(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString(),app:'Learning Studio'},null,2)],{type:'application/json'});download(blob,`learning-studio-backup-${today()}.json`);toast('Backup downloaded.')}
function exportNotes(){const md=state.notes.map(n=>`# ${n.title}\n\n- Category: ${n.category}\n- Updated: ${n.updatedAt}\n- Topic: ${topicById[n.topicId]?.title||'—'}\n- Tags: ${n.tags.map(t=>'#'+t).join(' ')}\n\n${n.content}\n`).join('\n---\n\n');download(new Blob([md],{type:'text/markdown'}),`learning-notes-${today()}.md`);toast('Notes exported.')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function importBackup(file){if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed||typeof parsed!=='object'||!parsed.progress||!Array.isArray(parsed.notes))throw Error('This file is not a Learning Studio backup.');modal={type:'confirm',title:'Restore this backup?',message:`This replaces current browser data with the backup from ${parsed.exportedAt?new Date(parsed.exportedAt).toLocaleDateString():'an unknown date'}. Export your current data first if you need it.`,confirm:'Restore backup',callback:()=>{const current=state;state={...baseState(),...parsed,settings:{...baseState().settings,...parsed.settings}};save();modal=null;render();toast('Backup restored.')}};render()}catch(e){toast(`Could not restore backup: ${e.message}`,'error')}}
function showGlobalSearch(q){const box=document.querySelector('#search-results');if(!box)return;if(!q.trim()){box.innerHTML='';box.classList.remove('visible');return}const term=q.toLowerCase(),hits=[];topics.filter(t=>textSearch(t).includes(term)).slice(0,4).forEach(t=>hits.push(`<button class="search-hit" data-topic="${t.id}"><span>⌘</span><b>${esc(t.title)}</b><small>Topic · ${esc(t.trackTitle)}</small></button>`));resources.filter(r=>`${r.title} ${r.topic} ${r.provider}`.toLowerCase().includes(term)).slice(0,3).forEach(r=>hits.push(`<button class="search-hit" data-search-resource="${r.id}"><span>↗</span><b>${esc(r.title)}</b><small>Resource · ${esc(r.topic)}</small></button>`));state.notes.filter(n=>`${n.title} ${n.content} ${n.tags.join(' ')}`.toLowerCase().includes(term)).slice(0,3).forEach(n=>hits.push(`<button class="search-hit" data-edit-note="${n.id}"><span>▤</span><b>${esc(n.title)}</b><small>Note · ${esc(n.category)}</small></button>`));box.innerHTML=hits.length?hits.join(''):`<div class="search-empty">No results for “${esc(q)}”</div>`;box.classList.add('visible');box.querySelectorAll('[data-topic]').forEach(x=>x.onclick=()=>{modal={type:'topic',id:x.dataset.topic};box.classList.remove('visible');render()});box.querySelectorAll('[data-edit-note]').forEach(x=>x.onclick=()=>{modal={type:'note',id:x.dataset.editNote};box.classList.remove('visible');render()});box.querySelectorAll('[data-search-resource]').forEach(x=>x.onclick=()=>{window.resourceQuery=resourceById[x.dataset.searchResource]?.title||q;view='resources';box.classList.remove('visible');render()})}
function uid(){return Math.random().toString(36).slice(2,9)+Date.now().toString(36)}
function toast(message,type='success'){const el=document.querySelector('#toast');if(!el)return;el.textContent=message;el.className=`toast visible ${type}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2800)}
function escapeHtml(v){return esc(v)}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#global-search')?.focus()}if(e.key==='Escape'&&modal){modal=null;render()}});
try { render(); } catch (e) { document.getElementById('app').innerHTML = `<pre style="padding:3rem;color:#b42318">${esc(e.stack||e.message)}</pre>`; console.error(e); }
})();
